// CURSOR
  const cursor = document.getElementById('cursor');
  const ring = document.getElementById('cursor-ring');
  let mx = 0, my = 0, rx = 0, ry = 0;
  document.addEventListener('mousemove', e => { mx = e.clientX; my = e.clientY; });
  function animCursor() {
    cursor.style.left = mx + 'px'; cursor.style.top = my + 'px';
    rx += (mx - rx) * 0.12; ry += (my - ry) * 0.12;
    ring.style.left = rx + 'px'; ring.style.top = ry + 'px';
    requestAnimationFrame(animCursor);
  }
  animCursor();

  // NAV SCROLL
  window.addEventListener('scroll', () => {
    document.getElementById('nav').classList.toggle('scrolled', window.scrollY > 50);
  });

  // REVEAL ON SCROLL
  const reveals = document.querySelectorAll('.reveal');
  const observer = new IntersectionObserver(entries => {
    entries.forEach((e, i) => {
      if (e.isIntersecting) {
        setTimeout(() => e.target.classList.add('visible'), 80);
        observer.unobserve(e.target);
      }
    });
  }, { threshold: 0.1, rootMargin: '0px 0px -60px 0px' });
  reveals.forEach(el => observer.observe(el));

  // STAGGER reveals in grid
  document.querySelectorAll('.skills-grid .skill-group, .projects-grid .project-card, .achievements-list .achievement-item').forEach((el, i) => {
    el.style.transitionDelay = `${i * 80}ms`;
  });

  // TILT effect on project cards
  document.querySelectorAll('.project-card').forEach(card => {
    card.addEventListener('mousemove', e => {
      const r = card.getBoundingClientRect();
      const x = (e.clientX - r.left) / r.width - 0.5;
      const y = (e.clientY - r.top) / r.height - 0.5;
      card.style.transform = `translateY(-4px) rotateX(${-y * 5}deg) rotateY(${x * 5}deg)`;
    });
    card.addEventListener('mouseleave', () => { card.style.transform = ''; });
  });

const RESUME_B64 = "";
  
  function b64ToBlob(b64) {
    const bin = atob(b64);
    const arr = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
    return new Blob([arr], {type: 'application/pdf'});
  }

  function downloadResume(e) {
    e.preventDefault();
    const blob = b64ToBlob(RESUME_B64);
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = 'Tiya_Verma_Resume.pdf';
    a.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }

  // Attach download to all resume download buttons
  document.querySelectorAll('.resume-dl-btn').forEach(btn => {
    btn.addEventListener('click', downloadResume);
  });

  let pdfRendered = false;

  async function renderPDF() {
    if (pdfRendered) return;
    pdfRendered = true;
    
    pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
    
    const blob = b64ToBlob(RESUME_B64);
    const url = URL.createObjectURL(blob);
    
    const container = document.getElementById('pdf-container');
    container.innerHTML = '';
    
    const loadingDiv = document.createElement('div');
    loadingDiv.style.cssText = 'display:flex;align-items:center;justify-content:center;height:100%;color:#666;font-family:monospace;font-size:12px;letter-spacing:0.2em;';
    loadingDiv.textContent = 'Loading resume...';
    container.appendChild(loadingDiv);

    try {
      const pdf = await pdfjsLib.getDocument(url).promise;
      container.innerHTML = '';
      
      for (let pageNum = 1; pageNum <= pdf.numPages; pageNum++) {
        const page = await pdf.getPage(pageNum);
        const viewport = page.getViewport({ scale: 1.6 });
        
        const canvas = document.createElement('canvas');
        canvas.style.cssText = 'display:block; margin: 0 auto 2px; max-width:100%;';
        canvas.width = viewport.width;
        canvas.height = viewport.height;
        container.appendChild(canvas);
        
        await page.render({ canvasContext: canvas.getContext('2d'), viewport }).promise;
      }
      URL.revokeObjectURL(url);
    } catch(err) {
      container.innerHTML = '<div style="padding:40px;color:#666;font-family:monospace;font-size:12px;">Could not render PDF preview. Please use the Download button.</div>';
      console.error(err);
    }
  }

  // Open modal and render
  function openResumeModal() {
    document.getElementById('resume-modal').style.display = 'flex';
    renderPDF();
  }